//remix of https://www.shadertoy.com/view/DtycDc

const vec3 scales = vec3(
   4.,4.,8.
);

#define triwave(p) abs(fract(.5+p/scales[0])-.5)*2.
#define triwave1(p) (abs(fract(p/scales[1])-.5)-abs(fract(p/scales[2])-.5)/2.)

vec4 t1(vec2 c, vec2 p){
    return triwave((.5 - length( min(p=fract(p*sign(triwave1(c*c.y))), 1.-p.yx) )) * vec4(22,7,5,0));
}

void mainImage(out vec4 O, vec2 I)
{
    vec2 p = (I/1e2+iTime/4.);
    vec4 t_ = t1(ceil(p),p);
    vec4 t1_ = vec4(0.),
    t3_ = vec4(0.);
    float scale = 2.;
    for(int i = 0; i < 3;i++){
        t1_ = t1(ceil(p/scale+.5),p/scale);
        scale *= 2.;
        t3_ =
            1.-min(fract(t_*scale/8.+iTime/2.),1.-t1_);
        if(
            t_.y>t_.x
        ) t_ =
            1.-t1_
        ;
    }
    O = t3_;
}

//remix of https://www.shadertoy.com/view/lcS3zy

float fmod(float a, float b, float tempo){
    float
    t1 = mod(floor(b/2.),2.),
    a1 =
        floor(a+t1),
    a2 = mod(a1+1.,3.),
    a3 =
        mod(a1+mod(a1/8.,3.)*8.,4.)
    ;
    return
        mod(a1-a2-a3,b)
    ;
}

float fmod(float a, float b){
    return fmod(a,b,1.);
}

float prime_rhythm(float time){
    return (1.+fmod(time/4.,2.))/(1.+fmod(time/2.,2.));
}

#define fract1(a) (1.-pow(fract(-a),2.))
//#define fract1(a) pow(1.-fract(-a)*fract(-a),1.-fract(a)*fract(a))
//#define fract1(a) pow(fract(a),1.-fract(a))


vec2 sitar6(vec2 a, vec2 nb){
    return a*a/16./2.*abs((.5*abs(1./8.-abs(.5-vec2(fract1(nb.x*4.*.998),fract1(nb.y*4.)))/2.))
      -(a/4.*abs(1./4.-abs(.5-vec2(fract1(nb.x*2.*.998),fract1(nb.y*2.)))/2.))) 
    ;
}

vec2 sitar7(vec2 a, vec2 nb){
    return sitar6(a,nb)-sitar6(a,nb)/2.;
}
vec2 sitar5(vec2 a, vec2 nb){
    return a*a/16./4.*abs((abs(1./8.-abs(.5-vec2(fract1(nb.x*4.*.998),fract1(nb.y*4.)))/2.))
      -(a*abs(1./4.-abs(.5-vec2(fract1(nb.x*2.*.998),fract1(nb.y*2.)))/2.))) 
    ;
}


#define tanpura(a,nb) (sitar0(a/2.,nb) - sitar0(a,nb))
vec2 sitar0(vec2 a, vec2 nb){
return a/16./2.*abs(log(1./8.+.5*a*abs(1./8.-abs(.5-vec2(fract1(nb.x*4.*.998),fract1(nb.y*4.)))/2.))
